public class MathDemo {
    public static void main(String[] args) {
        System.out.println(Math.sqrt(144));          // 12.0
        System.out.println(Math.pow(2, 10));         // 1024.0
        System.out.println(Math.abs(-57));           // 57
        System.out.println(Math.max(18, 24));        // 24
        System.out.println(Math.round(4.5));         // 5
        System.out.println(Math.round(4.4));         // 4
        System.out.println(Math.ceil(4.1));          // 5.0
        System.out.println(Math.floor(4.9));         // 4.0

        // Trigonometry works in radians, convert from degrees first
        System.out.println(Math.sin(Math.toRadians(30)));   // 0.49999999999999994
    }
}
